import{_ as t,c as o,o as a,a2 as r}from"./chunks/framework.CIiVzG-O.js";const h=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1785933680000}'),n={name:"guide/faq.md"};function s(i,e,p,l,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p><strong>Q: What is ClipboardxAI?</strong></p><p>A: ClipboardxAI is a smart clipboard manager for macOS. It keeps a searchable history of everything you copy and lets you run actions on it — summarize, translate, tidy text, or send it to a cloud AI model.</p><p><strong>Q: Which macOS versions are supported?</strong></p><p>A: macOS 14 Sonoma or later, optimized for Apple Silicon (M-series) with Intel support.</p><p><strong>Q: How do I install it?</strong></p><p>A: Download from the <a href="/">Mac App Store</a> (recommended) or grab the latest build from <a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub Releases</a>. See the <a href="/guide/installation.html">Installation Guide</a>.</p><p><strong>Q: Is ClipboardxAI free?</strong></p><p>A: The app is free to download. Built-in local tools need no account. Cloud AI actions use <em>your own</em> provider API key, so you only pay the AI provider directly — there is no paid tier in the app.</p><p><strong>Q: Which AI providers are supported?</strong></p><p>A: Any OpenAI-compatible provider: DeepSeek, MiniMax, Zhipu GLM, Kimi (Moonshot), Mistral, and local Ollama — plus OpenAI, Anthropic, and Gemini. Your key is stored in the Keychain.</p><p><strong>Q: Does it work offline?</strong></p><p>A: Yes. Clipboard history and the built-in local tools (extract links, count stats, collapse blank lines, and more) run entirely on your Mac with no internet connection.</p><p><strong>Q: Is my clipboard data private?</strong></p><p>A: Your history stays on your device. Cloud AI is opt-in and sends content only to the provider you configure, using a key from your Keychain. We never receive or store your clips, and there is no telemetry. See the <a href="/guide/privacy.html">Privacy Policy</a>.</p><p><strong>Q: How do I add more actions?</strong></p><p>A: Browse the <a href="/marketplace/">Marketplace</a> and click <strong>Install</strong> on any action. It opens the app via a deep link and appears in your <strong>Installed</strong> list.</p><p><strong>Q: How do I update the app?</strong></p><p>A: The Mac App Store version updates automatically. For GitHub builds, download the latest release and replace the app in <code>Applications</code>.</p><p><strong>Q: How do I report bugs or request features?</strong></p><p>A: Open an issue on the <a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub repository</a>. Include your macOS version, app version, and steps to reproduce.</p><p><strong>Q: Where is my data stored?</strong></p><p>A: In the sandboxed container:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.clipboard/Data/Library/Application Support/com.w3cub.clipboard/</span></span></code></pre></div><p>API keys live in the system Keychain, not in that folder.</p>',25)])])}const g=t(n,[["render",s]]);export{h as __pageData,g as default};
